73	class WorksHoverVideoRuntime {
74	  private readonly _video: HTMLVideoElement;
75	  private _texture: THREE.CanvasTexture | null = null;
76	  private _proj: WorkProjectItem | null = null;
77	  private _size: WorkCardSize | null = null;
78	  private _staticImage: HTMLImageElement | null = null;
79	  private _alpha = 0;
80	  private _alphaTarget = 0;
81	
82	  constructor() {
83	    const video = document.createElement("video");
84	    video.muted = true;
85	    video.loop = true;
86	    video.playsInline = true;
87	    video.preload = "auto";
88	    this._video = video;
89	  }
90	
91	  isActive(): boolean {
92	    return this._texture !== null;
93	  }
94	
95	  activate(
96	    mesh: THREE.Mesh,
97	    texture: THREE.CanvasTexture,
98	    videoUrl: string,
99	    proj: WorkProjectItem,
100	    size: WorkCardSize,
101	    staticImage: HTMLImageElement | null,
102	  ): void {
103	    this._texture = texture;
104	    this._proj = proj;
105	    this._size = size;
106	    this._staticImage = staticImage ?? null;
107	    this._alpha = 0;
108	    this._alphaTarget = 1;
109	    if (this._video.src !== videoUrl) {
110	      this._video.src = videoUrl;
111	      this._video.load();
112	    }
113	    void this._video.play().catch(() => undefined);
114	  }
115	
116	  deactivate(): void {
117	    this._video.pause();
118	    this._alphaTarget = 0;
119	  }
120	
121	  drawFrame(): void {
122	    if (!this._texture || !this._proj || !this._size) return;
123	
124	    this._alpha += (this._alphaTarget - this._alpha) * 0.12;
125	
126	    if (this._alphaTarget === 0 && this._alpha < 0.01) {
127	      WorkCard.updateTextureImage(
128	        this._texture,
129	        this._proj,
130	        this._size,
131	        this._staticImage ?? new Image(),
132	        SCATTER_CARD_RENDER_OPTIONS,
133	      );
134	      this._texture = null;
135	      this._proj = null;
136	      this._size = null;
137	      this._staticImage = null;
138	      this._alpha = 0;
139	      return;
140	    }
141	
142	    if (this._alpha > 0.99 && this._alphaTarget === 1) {
143	      WorkCard.updateTextureVideoFrame(
144	        this._texture,
145	        this._proj,
146	        this._size,
147	        this._video,
148	        SCATTER_CARD_RENDER_OPTIONS,
149	      );
150	      return;
151	    }
152	
153	    WorkCard.updateTextureImage(
154	      this._texture,
155	      this._proj,
156	      this._size,
157	      this._staticImage ?? new Image(),
158	      SCATTER_CARD_RENDER_OPTIONS,
159	    );
160	    WorkCard.overlayVideoFrame(this._texture, this._size, this._video, this._alpha);
161	  }
162	
163	  dispose(): void {
164	    this._video.pause();
165	    this._video.src = "";
166	    this._texture = null;
167	    this._proj = null;
168	    this._size = null;
169	    this._staticImage = null;
170	  }
171	}
