173	class WorksViewportRuntime {
174	  private readonly _pixelRatioMax: number;
175	
176	  constructor(pixelRatioMax: number) {
177	    this._pixelRatioMax = pixelRatioMax;
178	  }
179	
180	  read(): WorksViewportSnapshot {
181	    const snapshot = ResponsiveRuntime.getDefault().getSnapshot();
182	    return {
183	      width: snapshot.viewportWidth,
184	      height: snapshot.viewportHeight,
185	      dpr: Math.min(snapshot.render.clampedPixelRatio, this._pixelRatioMax),
186	    };
187	  }
188	
189	  readHalfView(camera: THREE.Camera): WorksHalfViewBounds {
190	    if (camera instanceof THREE.OrthographicCamera) {
191	      return {
192	        hW: (camera.right - camera.left) * 0.5,
193	        hH: (camera.top - camera.bottom) * 0.5,
194	      };
195	    }
196	    const perspectiveCamera = camera as THREE.PerspectiveCamera;
197	    const fov = (perspectiveCamera.fov * Math.PI) / 180;
198	    const halfHeight = Math.tan(fov / 2) * perspectiveCamera.position.z;
199	    return {
200	      hW: halfHeight * perspectiveCamera.aspect,
201	      hH: halfHeight,
202	    };
203	  }
204	}
