206	class WorksHitRuntime {
207	  private readonly _raycaster = new THREE.Raycaster();
208	  private readonly _mouse2d = new THREE.Vector2();
209	
210	  resolve(
211	    camera: THREE.Camera,
212	    viewport: WorksViewportSnapshot,
213	    pointer: WorksPointerSample,
214	    meshes: THREE.Mesh[],
215	  ): THREE.Mesh | null {
216	    this._mouse2d.set(
217	      (pointer.x / viewport.width) * 2 - 1,
218	      -(pointer.y / viewport.height) * 2 + 1,
219	    );
220	    this._raycaster.setFromCamera(this._mouse2d, camera);
221	    const hit = this._raycaster.intersectObjects(meshes, false)[0];
222	    return (hit?.object as THREE.Mesh | undefined) ?? null;
223	  }
224	}
