372	class WorksMeshRuntime {
373	  create(
374	    scene: THREE.Scene,
375	    projects: ReadonlyArray<WorkProjectItem>,
376	    positions: ReadonlyArray<WorksScatterPosition>,
377	    config: WorkCanvasConfig,
378	  ): WorksSceneCardMeshResources {
379	    const cardSize: WorkCardSize = {
380	      w: config.cardWidth,
381	      h: config.cardHeight,
382	    };
383	    const meshes: THREE.Mesh[] = [];
384	    positions.forEach((position, placed) => {
385	      const project = projects[placed % projects.length];
386	      const detailPath = project?.detailPath ?? "/works";
387	      const mesh = WorkCard.createMesh(
388	        project,
389	        cardSize,
390	        detailPath,
391	        SCATTER_CARD_RENDER_OPTIONS,
392	      );
393	      mesh.position.set(position.x, position.y, 0);
394	      scene.add(mesh);
395	      meshes.push(mesh);
396	    });
397	    return {
398	      meshes,
399	      cardSize,
400	    };
401	  }
402	
403	  dispose(meshes: ReadonlyArray<THREE.Mesh>): void {
404	    meshes.forEach((mesh) => {
405	      const material = mesh.material as THREE.MeshBasicMaterial;
406	      material.map?.dispose();
407	      material.dispose();
408	      mesh.geometry.dispose();
409	    });
410	  }
411	}
