413	class WorksThumbnailRuntime {
414	  async warm(
415	    meshes: ReadonlyArray<THREE.Mesh>,
416	    placeholderImage: string,
417	    cardSize: WorkCardSize,
418	    log: (step: string, payload?: Record<string, unknown>) => void,
419	    onImageLoaded?: (mesh: THREE.Mesh, image: HTMLImageElement) => void,
420	  ): Promise<void> {
421	    let fallback: HTMLImageElement | null = null;
422	    const ensureFallback = async (): Promise<HTMLImageElement> => {
423	      if (!fallback) {
424	        fallback = await WorkCard.loadPlaceholderImage(placeholderImage);
425	      }
426	      return fallback;
427	    };
428	
429	    let index = 0;
430	    const batchSize = 4;
431	    const runBatch = async (): Promise<void> => {
432	      const end = Math.min(index + batchSize, meshes.length);
433	      const slice = meshes.slice(index, end);
434	      await Promise.all(
435	        slice.map(async (mesh) => {
436	          if (!mesh) return;
437	          const userData = mesh.userData as WorkCardUserData;
438	          const material = mesh.material as THREE.MeshBasicMaterial;
439	          const map = material.map;
440	          if (!map || !(map instanceof THREE.CanvasTexture)) return;
441	          const thumb = userData.proj.thumbnailImage?.trim() ?? "";
442	          let img: HTMLImageElement;
443	          if (thumb) {
444	            try {
445	              img = await WorkCard.loadImage(thumb);
446	            } catch {
447	              img = await ensureFallback();
448	            }
449	          } else {
450	            img = await ensureFallback();
451	          }
452	          WorkCard.updateTextureImage(
453	            map,
454	            userData.proj,
455	            cardSize,
456	            img,
457	            SCATTER_CARD_RENDER_OPTIONS,
458	          );
459	          onImageLoaded?.(mesh, img);
460	        }),
461	      );
462	      index = end;
463	      log("warmThumbnails.batch", { updatedUntil: index, total: meshes.length });
464	      if (index < meshes.length) {
465	        FrameScheduler.request(() => {
466	          void runBatch();
467	        });
468	      }
469	    };
470	    void runBatch();
471	  }
472	}
