474	export class WorksSceneManager {
475	  private static readonly _dragStartThresholdPx = 10;
476	  /** 카테고리 전환 시 등장/퇴장 이징 길이(ms) — 전체 복귀 시 숨겨졌던 카드도 위치·투명도가 눈에 띄게 변함 */
477	  private static readonly _filterBlendMs = 480;
478	  private readonly root: ParentNode;
479	  private readonly config: WorkCanvasConfig;
480	  private readonly layout: WorkLayoutConstants;
481	  private readonly projects: ReadonlyArray<WorkProjectItem>;
482	  private readonly canvasId: string;
483	  private readonly rendererConfig: WorksRendererConfig;
484	  private readonly placeholderImage: string;
485	  private readonly introEntryState: WorksSceneManagerOptions["introEntryState"];
486	  private readonly viewportRuntime: WorksViewportRuntime;
487	  private readonly hitRuntime = new WorksHitRuntime();
488	  private readonly meshRuntime = new WorksMeshRuntime();
489	  private readonly thumbnailRuntime = new WorksThumbnailRuntime();
490	  private readonly cameraMotionRuntime: WorksCameraMotionRuntime;
491	  private readonly onSelect?: (detailPath: string) => void;
492	  private readonly onInteractionStart?: () => void;
493	  private canvas: HTMLCanvasElement | null = null;
494	  private scene: THREE.Scene | null = null;
495	  private camera: THREE.Camera | null = null;
496	  private renderer: THREE.WebGLRenderer | null = null;
497	  private meshes: THREE.Mesh[] = [];
498	  private rafId: number | null = null;
499	  private cleanup: Array<() => void> = [];
500	  private viewMode: WorksViewMode = "scatter";
501	  private clock: THREE.Clock | null = null;
502	  private activePointerId: number | null = null;
503	  private hovered: THREE.Mesh | null = null;
504	  private _prevHovered: THREE.Mesh | null = null;
505	  private _cardScale = 1;
506	  private _cardSize: WorkCardSize = { w: 10, h: 6.9 };
507	  private _isTouchPointer = false;
508	  private readonly _hoverVideo = new WorksHoverVideoRuntime();
509	  private mouseDownX = 0;
510	  private mouseDownY = 0;
511	  private mouseDownMesh: THREE.Mesh | null = null;
512	  private dragInteractionStarted = false;
513	  private readonly camPadX: number;
514	  private readonly camPadY: number;
515	  private scatterPositions: WorksScatterPosition[];
516	  private categoryScatterPositions: WorksScatterPosition[];
517	  private targetPositions: WorksScatterPosition[] = [];
518	  private interactiveMeshes: THREE.Mesh[] = [];
519	  private activeCategory: string | null;
520	  /** 직전 `applyCategory` 호출 직전의 필터 (전환 이징용) */
521	  private _filterPrevCategory: string | null = null;
522	  private _filterBlendStartMs = 0;
523	
524	  constructor(options: WorksSceneManagerOptions) {
525	    this.root = options.root;
526	    this.config = options.config;
527	    this.layout = options.layout;
528	    this.projects = options.projects;
529	    this.canvasId = options.canvasId;
530	    this.rendererConfig = options.renderer;
531	    this.placeholderImage = options.placeholderImage;
532	    this.introEntryState = options.introEntryState ?? null;
533	    this.onSelect = options.onSelect;
534	    this.onInteractionStart = options.onInteractionStart;
535	    this.activeCategory = options.initialCategory ?? null;
536	    this.camPadX = options.config.spreadX * 0.5 + 5;
537	    this.camPadY = options.config.spreadY * 0.5 + 5;
538	    this.viewportRuntime = new WorksViewportRuntime(options.pixelRatioMax);
539	    this.cameraMotionRuntime = new WorksCameraMotionRuntime(
540	      options.layout,
541	      this.camPadX,
542	      this.camPadY,
543	      options.config.camZ,
544	    );
545	    this.scatterPositions = buildScatterPositions(
546	      options.config.totalCards,
547	      options.config.spreadX,
548	      options.config.spreadY * 0.88,
549	    );
550	    this.categoryScatterPositions = sortScatterPositionsFromCenter(this.scatterPositions);
551	    this.targetPositions = [...this.scatterPositions];
552	  }
553	
554	  private _rebuildScatterPositions(): void {
555	    const scale = this._cardScale;
556	    this.scatterPositions = buildScatterPositions(
557	      this.config.totalCards,
558	      this.config.spreadX * scale,
559	      this.config.spreadY * 0.88 * scale,
560	    );
561	    this.categoryScatterPositions = sortScatterPositionsFromCenter(this.scatterPositions);
562	  }
563	
564	  init(): void {
565	    if (this.projects.length === 0) return;
566	    this.start();
567	  }
568	
569	  setViewMode(mode: WorksViewMode): void {
570	    if (this.viewMode === mode) return;
571	    this.viewMode = mode;
572	    if (mode === "grid") {
573	      this._hoverVideo.deactivate();
574	      this._prevHovered = null;
575	      this.hovered = null;
576	      this.mouseDownMesh = null;
577	      this.dragInteractionStarted = false;
578	      this.activePointerId = null;
579	      this.cameraMotionRuntime.endDrag();
580	      this.stopLoop();
581	      return;
582	    }
583	    this.cameraMotionRuntime.activateScatter();
584	    this.startLoop();
585	  }
586	
587	  applyCategory(category: string | null): void {
588	    if (this.activeCategory !== category) {
589	      this._filterPrevCategory = this.activeCategory;
590	      this._filterBlendStartMs = performance.now();
591	    }
592	    this.activeCategory = category;
593	    const scatterPositions = this.categoryScatterPositions;
594	    const nextPositions = [...this.scatterPositions];
595	    const nextInteractiveMeshes: THREE.Mesh[] = [];
596	    const visiblePositions: WorksScatterPosition[] = [];
597	    let visibleIndex = 0;
598	    for (let index = 0; index < this.meshes.length; index += 1) {
599	      const mesh = this.meshes[index];
600	      if (!mesh || !this.isMeshInCategory(mesh)) continue;
601	      nextInteractiveMeshes.push(mesh);
602	      const targetPosition = scatterPositions[visibleIndex] ?? this.scatterPositions[index];
603	      nextPositions[index] = targetPosition;
604	      visiblePositions.push(targetPosition);
605	      visibleIndex += 1;
606	    }
607	    this.targetPositions = nextPositions;
608	    this.interactiveMeshes = nextInteractiveMeshes;
609	    this._centerCameraOnVisiblePositions(visiblePositions);
610	    this.cameraMotionRuntime.setTargetZ(this.cameraMotionRuntime.readBaseCamZ());
611	    this.cameraMotionRuntime.setDynamicClamp(visiblePositions);
612	    if (this.hovered && !this.isMeshInCategory(this.hovered)) this.hovered = null;
613	  }
614	
615	  showCanvas(): void {
616	    if (!this.canvas) return;
617	    this.canvas.classList.remove("is-hidden", "is-transitioning-out");
618	    Aria.setHidden(this.canvas, false);
619	    this.canvas.style.opacity = "1";
