688	    const positionFactor = 1 - Math.pow(1 - this.layout.positionLerp, delta * 60);
689	    const opacityFactor = 1 - Math.pow(1 - this.layout.opacityLerp, delta * 60);
690	    const scaleFactor = 1 - Math.pow(1 - this.layout.scaleLerp, delta * 60);
