698	            (performance.now() - this._filterBlendStartMs) /
699	              WorksSceneManager._filterBlendMs,
700	          )
701	        : 1;
702	    const filterEase = 1 - Math.pow(1 - blendT, 3);
703	    for (let index = 0; index < this.meshes.length; index += 1) {
704	      const mesh = this.meshes[index];
705	      const target = this.targetPositions[index] ?? this.scatterPositions[index];
706	      const isActiveCategory = this.isMeshInCategory(mesh);
707	      const wasIn = this._meshIncludedInFilter(mesh, this._filterPrevCategory);
708	      const nowIn = isActiveCategory;
709	      let targetY = target.y;
710	      if (wasIn && !nowIn && blendT < 1) {
